import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"Kernel 日报 2026-11-21","description":"","frontmatter":{},"headers":[],"relativePath":"notes/kernel-digest/2026/11/21.md","filePath":"notes/kernel-digest/2026/11/21.md"}'),n={name:"notes/kernel-digest/2026/11/21.md"};function l(i,e,c,s,d,p){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="kernel-日报-2026-11-21" tabindex="-1">Kernel 日报 2026-11-21 <a class="header-anchor" href="#kernel-日报-2026-11-21" aria-label="Permalink to &quot;Kernel 日报 2026-11-21&quot;">​</a></h1><blockquote><p>生成时间：2026-11-21T02:29:55Z｜共 22 条</p></blockquote><blockquote><p>深读：使用条目前 12 位 id，运行 <code>python -m kernel_digest deep --date 2026-11-21 --id &lt;id&gt;</code>。</p></blockquote><h2 id="今日-top-5" tabindex="-1">今日 Top 5 <a class="header-anchor" href="#今日-top-5" aria-label="Permalink to &quot;今日 Top 5&quot;">​</a></h2><h3 id="_766458ca1197-·-gnupg-s-gpgme-affected-by-critical-security-bug-in-turn-affecting-mail-clients-flatpak" tabindex="-1"><code>766458ca1197</code> · <a href="https://www.phoronix.com/news/GnuPG-GPGME-Critical" target="_blank" rel="noreferrer">GnuPG&#39;s GPGME Affected By Critical Security Bug In Turn Affecting Mail Clients, Flatpak</a> <a class="header-anchor" href="#_766458ca1197-·-gnupg-s-gpgme-affected-by-critical-security-bug-in-turn-affecting-mail-clients-flatpak" aria-label="Permalink to &quot;`766458ca1197` · [GnuPG&#39;s GPGME Affected By Critical Security Bug In Turn Affecting Mail Clients, Flatpak](https://www.phoronix.com/news/GnuPG-GPGME-Critical)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix｜其他动态</em></p><p>Werner Koch 宣布 GnuPG 的 GPGME 库存在一个 critical 安全漏洞。该漏洞影响大多数邮件客户端、多数 XMPP 客户端、Flatpak、Samba 等依赖 GPGME 的软件。</p><blockquote><p><strong>学习价值</strong>：用户态加密库的安全事件，提醒学习者关注内核之外的供应链安全面。</p></blockquote><h3 id="_9ae505c031bc-·-patch-net-ice-do-not-report-checksum-complete-when-an-xdp-program-is-attached" tabindex="-1"><code>9ae505c031bc</code> · <a href="https://lore.kernel.org/all/20261121012402.84848-1-tianyi@cloudflare.com/" target="_blank" rel="noreferrer">[PATCH net] ice: do not report CHECKSUM_COMPLETE when an XDP program is attached</a> <a class="header-anchor" href="#_9ae505c031bc-·-patch-net-ice-do-not-report-checksum-complete-when-an-xdp-program-is-attached" aria-label="Permalink to &quot;`9ae505c031bc` · [[PATCH net] ice: do not report CHECKSUM_COMPLETE when an XDP program is attached](https://lore.kernel.org/all/20261121012402.84848-1-tianyi@cloudflare.com/)&quot;">​</a></h3><p><em>Tianyi Gao (<a href="mailto:tianyi@cloudflare.com" target="_blank" rel="noreferrer">tianyi@cloudflare.com</a>)｜netdev｜网络</em></p><p>Cloudflare 工程师修复 ice 驱动在 E830 网卡上的问题：当 XDP 程序修改数据包并返回 XDP_PASS 后，硬件计算的 generic checksum（GCS）不再匹配，导致 netdev_rx_csum_fault() 频繁触发。修复方案是在 RX ring 挂载 XDP 程序时不使用 GCS 报告 CHECKSUM_COMPLETE，与 mlx5 的既有做法保持一致。</p><blockquote><p><strong>学习价值</strong>：真实生产环境中 XDP 与硬件 checksum 卸载交互的经典案例，展示了 XDP 程序修改报文对协议栈校验和假设的影响。</p></blockquote><h3 id="_6a656cb76a4a-·-patch-v2-rust-bindgen-preserve-sched-statistics-alignment" tabindex="-1"><code>6a656cb76a4a</code> · <a href="https://lore.kernel.org/all/20261120-fix-schedstats-bindgen-layout-v2-1-1c42e4a996ae@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2] rust: bindgen: Preserve sched_statistics alignment</a> <a class="header-anchor" href="#_6a656cb76a4a-·-patch-v2-rust-bindgen-preserve-sched-statistics-alignment" aria-label="Permalink to &quot;`6a656cb76a4a` · [[PATCH v2] rust: bindgen: Preserve sched_statistics alignment](https://lore.kernel.org/all/20261120-fix-schedstats-bindgen-layout-v2-1-1c42e4a996ae@gmail.com/)&quot;">​</a></h3><p><em>Peder Bergan via B4 Relay (<a href="mailto:devnull+peder.bergan.gmail.com@kernel.org" target="_blank" rel="noreferrer">devnull+peder.bergan.gmail.com@kernel.org</a>)｜rust-for-linux｜Rust in Linux</em></p><p>修复 bindgen 生成的 struct sched_statistics 对齐问题：当 CONFIG_SCHEDSTATS 关闭时该结构体为空但仍保持 cache-line 对齐，而 bindgen 会忽略空类型的对齐，导致 task_struct 中后续字段错位，arm64 上 Rust Binder 通过 CurrentTask::mm() 读到错误指针而拒绝 mmap()。解决方案是将 sched_statistics 声明为 opaque 类型，使 bindgen 使用 C 侧的大小和对齐信息。</p><blockquote><p><strong>学习价值</strong>：极佳的案例，说明 C 与 Rust ABI 交互中结构体对齐/padding 的陷阱，以及 opaque 类型在 bindgen 中的重要作用。</p></blockquote><h3 id="_827ba10c2f54-·-amdxdna-driver-reaches-version-1-0-ryzen-ai-npu10-npu11-coming-to-linux-7-5" tabindex="-1"><code>827ba10c2f54</code> · <a href="https://www.phoronix.com/news/AMDXDNA-1.0-Linux-Driver" target="_blank" rel="noreferrer">AMDXDNA Driver Reaches Version 1.0, Ryzen AI NPU10 &amp; NPU11 Coming To Linux 7.5</a> <a class="header-anchor" href="#_827ba10c2f54-·-amdxdna-driver-reaches-version-1-0-ryzen-ai-npu10-npu11-coming-to-linux-7-5" aria-label="Permalink to &quot;`827ba10c2f54` · [AMDXDNA Driver Reaches Version 1.0, Ryzen AI NPU10 &amp; NPU11 Coming To Linux 7.5](https://www.phoronix.com/news/AMDXDNA-1.0-Linux-Driver)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix｜其他动态</em></p><p>AMD 的 AMDXDNA 加速器驱动（用于支持 Ryzen AI NPU）将在 Linux 7.5 内核中宣布达到 1.0 版本，标志着该驱动趋于成熟稳定。同时，新一代 NPU10 和 NPU11 硬件的支持也在推进中。</p><blockquote><p><strong>学习价值</strong>：展示了内核加速器驱动从开发到稳定（1.0）的演进过程，适合了解 NPU 驱动子系统的成熟路径。</p></blockquote><h3 id="b3fd41928162-·-intel-preps-linux-7-5-change-to-better-handle-multiple-gpus-with-lots-of-vram" tabindex="-1"><code>b3fd41928162</code> · <a href="https://www.phoronix.com/news/Linux-7.5-DRM-8TB-mmap" target="_blank" rel="noreferrer">Intel Preps Linux 7.5 Change To Better Handle Multiple GPUs With Lots Of VRAM</a> <a class="header-anchor" href="#b3fd41928162-·-intel-preps-linux-7-5-change-to-better-handle-multiple-gpus-with-lots-of-vram" aria-label="Permalink to &quot;`b3fd41928162` · [Intel Preps Linux 7.5 Change To Better Handle Multiple GPUs With Lots Of VRAM](https://www.phoronix.com/news/Linux-7.5-DRM-8TB-mmap)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix｜其他动态</em></p><p>Intel 为即将到来的 Linux 7.5 内核周期准备了一项改动，将内核图形驱动中 GEM/TTM buffer object 的 mmap 范围上限从 1TB 扩展到最多 8TB，以更好地支持配备大容量 VRAM 的多 GPU 系统。</p><blockquote><p><strong>学习价值</strong>：涉及 DRM 子系统中 GEM/TTM 内存管理机制，是了解 GPU 显存地址空间管理的实用素材。</p></blockquote><h2 id="分类目录" tabindex="-1">分类目录 <a class="header-anchor" href="#分类目录" aria-label="Permalink to &quot;分类目录&quot;">​</a></h2><ul><li><strong>内存管理</strong>（1 条）</li><li><strong>网络</strong>（1 条）</li><li><strong>Rust in Linux</strong>（8 条）</li><li><strong>跟踪与性能</strong>（1 条）</li><li><strong>版本发布动态</strong>（1 条）</li><li><strong>其他动态</strong>（10 条）</li></ul><h2 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h2><h3 id="_1b0e16a5e167-·-akpm-mm-mm-new-build-success-15f114dac9a7bde1796f0e54e22726fd31cfa8a5" tabindex="-1"><code>1b0e16a5e167</code> · <a href="https://lore.kernel.org/all/20261121090457.sQENk6l3-lkp@intel.com/" target="_blank" rel="noreferrer">[akpm-mm:mm-new] BUILD SUCCESS 15f114dac9a7bde1796f0e54e22726fd31cfa8a5</a> <a class="header-anchor" href="#_1b0e16a5e167-·-akpm-mm-mm-new-build-success-15f114dac9a7bde1796f0e54e22726fd31cfa8a5" aria-label="Permalink to &quot;`1b0e16a5e167` · [[akpm-mm:mm-new] BUILD SUCCESS 15f114dac9a7bde1796f0e54e22726fd31cfa8a5](https://lore.kernel.org/all/20261121090457.sQENk6l3-lkp@intel.com/)&quot;">​</a></h3><p><em>kernel test robot (<a href="mailto:lkp@intel.com" target="_blank" rel="noreferrer">lkp@intel.com</a>)｜linux-mm</em></p><p>kernel test robot 报告 akpm 的 mm-new 分支在 commit 15f114da（lib/test_hmm: 修复拆分 device-private folios 时的 alloc tag 泄漏）上构建成功，覆盖 alpha 等多种架构和配置。该修复涉及 HMM（Heterogeneous Memory Management）测试代码中的内存泄漏问题。</p><blockquote><p><strong>学习价值</strong>：体现了 0-day/kbuild 测试机器人对 Andrew Morton 内存管理树的持续集成验证流程，是了解内核 CI 生态的好例子。</p></blockquote><h2 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h2><h3 id="_9ae505c031bc-·-patch-net-ice-do-not-report-checksum-complete-when-an-xdp-program-is-attached-1" tabindex="-1"><code>9ae505c031bc</code> · <a href="https://lore.kernel.org/all/20261121012402.84848-1-tianyi@cloudflare.com/" target="_blank" rel="noreferrer">[PATCH net] ice: do not report CHECKSUM_COMPLETE when an XDP program is attached</a> <a class="header-anchor" href="#_9ae505c031bc-·-patch-net-ice-do-not-report-checksum-complete-when-an-xdp-program-is-attached-1" aria-label="Permalink to &quot;`9ae505c031bc` · [[PATCH net] ice: do not report CHECKSUM_COMPLETE when an XDP program is attached](https://lore.kernel.org/all/20261121012402.84848-1-tianyi@cloudflare.com/)&quot;">​</a></h3><p><em>Tianyi Gao (<a href="mailto:tianyi@cloudflare.com" target="_blank" rel="noreferrer">tianyi@cloudflare.com</a>)｜netdev</em></p><p>Cloudflare 工程师修复 ice 驱动在 E830 网卡上的问题：当 XDP 程序修改数据包并返回 XDP_PASS 后，硬件计算的 generic checksum（GCS）不再匹配，导致 netdev_rx_csum_fault() 频繁触发。修复方案是在 RX ring 挂载 XDP 程序时不使用 GCS 报告 CHECKSUM_COMPLETE，与 mlx5 的既有做法保持一致。</p><blockquote><p><strong>学习价值</strong>：真实生产环境中 XDP 与硬件 checksum 卸载交互的经典案例，展示了 XDP 程序修改报文对协议栈校验和假设的影响。</p></blockquote><h2 id="rust-in-linux" tabindex="-1">Rust in Linux <a class="header-anchor" href="#rust-in-linux" aria-label="Permalink to &quot;Rust in Linux&quot;">​</a></h2><h3 id="_6a656cb76a4a-·-patch-v2-rust-bindgen-preserve-sched-statistics-alignment-1" tabindex="-1"><code>6a656cb76a4a</code> · <a href="https://lore.kernel.org/all/20261120-fix-schedstats-bindgen-layout-v2-1-1c42e4a996ae@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2] rust: bindgen: Preserve sched_statistics alignment</a> <a class="header-anchor" href="#_6a656cb76a4a-·-patch-v2-rust-bindgen-preserve-sched-statistics-alignment-1" aria-label="Permalink to &quot;`6a656cb76a4a` · [[PATCH v2] rust: bindgen: Preserve sched_statistics alignment](https://lore.kernel.org/all/20261120-fix-schedstats-bindgen-layout-v2-1-1c42e4a996ae@gmail.com/)&quot;">​</a></h3><p><em>Peder Bergan via B4 Relay (<a href="mailto:devnull+peder.bergan.gmail.com@kernel.org" target="_blank" rel="noreferrer">devnull+peder.bergan.gmail.com@kernel.org</a>)｜rust-for-linux</em></p><p>修复 bindgen 生成的 struct sched_statistics 对齐问题：当 CONFIG_SCHEDSTATS 关闭时该结构体为空但仍保持 cache-line 对齐，而 bindgen 会忽略空类型的对齐，导致 task_struct 中后续字段错位，arm64 上 Rust Binder 通过 CurrentTask::mm() 读到错误指针而拒绝 mmap()。解决方案是将 sched_statistics 声明为 opaque 类型，使 bindgen 使用 C 侧的大小和对齐信息。</p><blockquote><p><strong>学习价值</strong>：极佳的案例，说明 C 与 Rust ABI 交互中结构体对齐/padding 的陷阱，以及 opaque 类型在 bindgen 中的重要作用。</p></blockquote><h3 id="_9b7606e5f1a8-·-patch-v2-rust-put-c-helper-exports-in-a-dedicated-namespace" tabindex="-1"><code>9b7606e5f1a8</code> · <a href="https://lore.kernel.org/all/20261120-rust-helper-namespace-v2-1-14315658f59e@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2] rust: put C helper exports in a dedicated namespace</a> <a class="header-anchor" href="#_9b7606e5f1a8-·-patch-v2-rust-put-c-helper-exports-in-a-dedicated-namespace" aria-label="Permalink to &quot;`9b7606e5f1a8` · [[PATCH v2] rust: put C helper exports in a dedicated namespace](https://lore.kernel.org/all/20261120-rust-helper-namespace-v2-1-14315658f59e@gmail.com/)&quot;">​</a></h3><p><em>Peder Bergan via B4 Relay (<a href="mailto:devnull+peder.bergan.gmail.com@kernel.org" target="_blank" rel="noreferrer">devnull+peder.bergan.gmail.com@kernel.org</a>)｜rust-for-linux</em></p><p>将 rust_helper_ 前缀的 C 辅助函数导出到专用的 RUST_HELPERS namespace，使 modpost 能在构建时检测模块对实现细节的意外依赖。由于内联和泛型实例化可能引入对这些辅助函数的调用，由 module! 宏自动提供 namespace import。</p><blockquote><p><strong>学习价值</strong>：展示了内核符号导出 namespace 机制如何用于约束 Rust/C 互操作接口的可见性，是模块链接规范化的好教材。</p></blockquote><h3 id="_1c720b2d01de-·-patch-rust-put-c-helper-exports-in-a-dedicated-namespace" tabindex="-1"><code>1c720b2d01de</code> · <a href="https://lore.kernel.org/all/20261120-rust-helper-namespace-v1-1-3b9a05553ff6@gmail.com/" target="_blank" rel="noreferrer">[PATCH] rust: put C helper exports in a dedicated namespace</a> <a class="header-anchor" href="#_1c720b2d01de-·-patch-rust-put-c-helper-exports-in-a-dedicated-namespace" aria-label="Permalink to &quot;`1c720b2d01de` · [[PATCH] rust: put C helper exports in a dedicated namespace](https://lore.kernel.org/all/20261120-rust-helper-namespace-v1-1-3b9a05553ff6@gmail.com/)&quot;">​</a></h3><p><em>Peder Bergan via B4 Relay (<a href="mailto:devnull+peder.bergan.gmail.com@kernel.org" target="_blank" rel="noreferrer">devnull+peder.bergan.gmail.com@kernel.org</a>)｜rust-for-linux</em></p><p>该补丁是 id 5 的 v1 版本，同样将 rust_helper_ C 辅助函数导出到 RUST_HELPERS 专用 namespace，以便 modpost 在构建时标记缺失 namespace import 的意外依赖。v2 版本进一步处理了 KASAN 测试等场景下 Rust 对象链接进 C 模块的问题。</p><blockquote><p><strong>学习价值</strong>：与 v2 对照可学习补丁迭代过程中如何根据评审反馈完善边界场景处理。</p></blockquote><h3 id="e902463a09aa-·-patch-v6-12-12-rust-xarray-document-guard-lock-drop-semantics" tabindex="-1"><code>e902463a09aa</code> · <a href="https://lore.kernel.org/all/20261120-xarray-entry-send-v6-12-1f69d7385f70@kernel.org/" target="_blank" rel="noreferrer">[PATCH v6 12/12] rust: xarray: document <code>Guard</code> lock drop semantics</a> <a class="header-anchor" href="#e902463a09aa-·-patch-v6-12-12-rust-xarray-document-guard-lock-drop-semantics" aria-label="Permalink to &quot;`e902463a09aa` · [[PATCH v6 12/12] rust: xarray: document `Guard` lock drop semantics](https://lore.kernel.org/all/20261120-xarray-entry-send-v6-12-1f69d7385f70@kernel.org/)&quot;">​</a></h3><p><em>Andreas Hindborg (<a href="mailto:a.hindborg@kernel.org" target="_blank" rel="noreferrer">a.hindborg@kernel.org</a>)｜rust-for-linux</em></p><p>为 Rust XArray 绑定的 Guard 补充文档，说明 Guard::store 调用 __xa_store 时，若使用阻塞分配标志会临时释放 xarray 锁进行内存分配后再重新获取。这与 Rust 中 guard 应在整个生命周期内提供持续互斥的惯例不符，跨阻塞 store 的 check-then-act 序列并非原子操作，文档建议使用预分配内存的 entry API 来避免锁释放。</p><blockquote><p><strong>学习价值</strong>：深刻揭示了 Rust 锁 guard 语义与 C 内核 API 内部行为（锁释放重获取）的语义冲突，是理解 Rust 内核抽象安全契约的优质素材。</p></blockquote><h3 id="cf23baea5ebd-·-patch-v6-07-12-rust-xarray-add-entry-api" tabindex="-1"><code>cf23baea5ebd</code> · <a href="https://lore.kernel.org/all/20261120-xarray-entry-send-v6-7-1f69d7385f70@kernel.org/" target="_blank" rel="noreferrer">[PATCH v6 07/12] rust: xarray: add entry API</a> <a class="header-anchor" href="#cf23baea5ebd-·-patch-v6-07-12-rust-xarray-add-entry-api" aria-label="Permalink to &quot;`cf23baea5ebd` · [[PATCH v6 07/12] rust: xarray: add entry API](https://lore.kernel.org/all/20261120-xarray-entry-send-v6-7-1f69d7385f70@kernel.org/)&quot;">​</a></h3><p><em>Andreas Hindborg (<a href="mailto:a.hindborg@kernel.org" target="_blank" rel="noreferrer">a.hindborg@kernel.org</a>)｜rust-for-linux</em></p><p>为 Rust XArray 绑定新增 Entry API，模仿 Rust 标准库 HashMap 的 entry 模式，Guard::entry 返回 Vacant 或 Occupied 状态，支持高效的条件插入与修改。该 API 的设计动机来自 Rust null block driver 的内存后端实现需求。</p><blockquote><p><strong>学习价值</strong>：展示了如何将 Rust 标准库惯用 API 模式移植到内核数据结构绑定上，是学习内核 Rust API 设计的范例。</p></blockquote><h3 id="_3b3829432031-·-patch-v6-01-12-rust-xarray-minor-formatting-fixes" tabindex="-1"><code>3b3829432031</code> · <a href="https://lore.kernel.org/all/20261120-xarray-entry-send-v6-1-1f69d7385f70@kernel.org/" target="_blank" rel="noreferrer">[PATCH v6 01/12] rust: xarray: minor formatting fixes</a> <a class="header-anchor" href="#_3b3829432031-·-patch-v6-01-12-rust-xarray-minor-formatting-fixes" aria-label="Permalink to &quot;`3b3829432031` · [[PATCH v6 01/12] rust: xarray: minor formatting fixes](https://lore.kernel.org/all/20261120-xarray-entry-send-v6-1-1f69d7385f70@kernel.org/)&quot;">​</a></h3><p><em>Andreas Hindborg (<a href="mailto:a.hindborg@kernel.org" target="_blank" rel="noreferrer">a.hindborg@kernel.org</a>)｜rust-for-linux</em></p><p>对 rust xarray 模块进行格式清理以符合内核编码规范：use 语句改为每行一个导入的垂直布局、添加尾部空注释防止 rustfmt 折叠导入、将内核 crate 引用从 crate 改为 kernel、拆分过长的 assert_eq! 语句等。</p><blockquote><p><strong>学习价值</strong>：虽是格式修补，但可了解 Rust 内核代码的编码规范细节及与 rustfmt 工具的博弈技巧。</p></blockquote><h3 id="_6fe875d3a767-·-patch-v6-04-12-rust-xarray-add-xarraystate" tabindex="-1"><code>6fe875d3a767</code> · <a href="https://lore.kernel.org/all/20261120-xarray-entry-send-v6-4-1f69d7385f70@kernel.org/" target="_blank" rel="noreferrer">[PATCH v6 04/12] rust: xarray: add <code>XArrayState</code></a> <a class="header-anchor" href="#_6fe875d3a767-·-patch-v6-04-12-rust-xarray-add-xarraystate" aria-label="Permalink to &quot;`6fe875d3a767` · [[PATCH v6 04/12] rust: xarray: add `XArrayState`](https://lore.kernel.org/all/20261120-xarray-entry-send-v6-4-1f69d7385f70@kernel.org/)&quot;">​</a></h3><p><em>Andreas Hindborg (<a href="mailto:a.hindborg@kernel.org" target="_blank" rel="noreferrer">a.hindborg@kernel.org</a>)｜rust-for-linux</em></p><p>为 Rust XArray 绑定新增内部状态结构 XArrayState，封装 C 侧的 xa_state 并持有 Guard 引用以保证独占访问。通过 Deref bound 泛型化 guard 借用，可持有共享或可变引用；Guard::load 改用 xas_load 替代 xa_load，避免后者内部不必要的 RCU 加锁。</p><blockquote><p><strong>学习价值</strong>：深入展示了如何将 C 内核的 xas_* 状态机 API 封装为类型安全的 Rust 抽象，并优化掉冗余的 RCU 锁获取。</p></blockquote><h3 id="_1fc120e674e2-·-patch-v6-06-12-rust-xarray-add-find-next-and-find-next-mut" tabindex="-1"><code>1fc120e674e2</code> · <a href="https://lore.kernel.org/all/20261120-xarray-entry-send-v6-6-1f69d7385f70@kernel.org/" target="_blank" rel="noreferrer">[PATCH v6 06/12] rust: xarray: add <code>find_next</code> and <code>find_next_mut</code></a> <a class="header-anchor" href="#_1fc120e674e2-·-patch-v6-06-12-rust-xarray-add-find-next-and-find-next-mut" aria-label="Permalink to &quot;`1fc120e674e2` · [[PATCH v6 06/12] rust: xarray: add `find_next` and `find_next_mut`](https://lore.kernel.org/all/20261120-xarray-entry-send-v6-6-1f69d7385f70@kernel.org/)&quot;">​</a></h3><p><em>Andreas Hindborg (<a href="mailto:a.hindborg@kernel.org" target="_blank" rel="noreferrer">a.hindborg@kernel.org</a>)｜rust-for-linux</em></p><p>本补丁为 Rust 的 XArray 抽象层新增 <code>find_next</code> 和 <code>find_next_mut</code> 方法，用于从指定 index 开始查找下一个元素，并返回元素所在 index 与引用。实现基于 XArray state API 的 <code>xas_find</code>，由于 <code>Guard</code> 已持有 exclusive lock，因此无需再获取 RCU lock。</p><blockquote><p><strong>学习价值</strong>：通过这个补丁可以学习如何在 Rust 中封装 C 内核的 XArray state API，以及理解 RCU 与锁的交互关系，是 Rust in Linux 抽象层设计的良好范例。</p></blockquote><h2 id="跟踪与性能" tabindex="-1">跟踪与性能 <a class="header-anchor" href="#跟踪与性能" aria-label="Permalink to &quot;跟踪与性能&quot;">​</a></h2><h3 id="f21dc6a34d3e-·-system76-thelio-prime-a-petite-but-performant-amd-powered-linux-pc" tabindex="-1"><code>f21dc6a34d3e</code> · <a href="https://www.phoronix.com/review/system76-thelio-prime" target="_blank" rel="noreferrer">System76 Thelio Prime: A Petite But Performant AMD-Powered Linux PC</a> <a class="header-anchor" href="#f21dc6a34d3e-·-system76-thelio-prime-a-petite-but-performant-amd-powered-linux-pc" aria-label="Permalink to &quot;`f21dc6a34d3e` · [System76 Thelio Prime: A Petite But Performant AMD-Powered Linux PC](https://www.phoronix.com/review/system76-thelio-prime)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>System76 发布重新设计的 Thelio Prime 迷你台式机，搭载 AMD Ryzen 9000 系列处理器（最高 Ryzen 9 9900X），可选 AMD 或 NVIDIA 独显，最高 96GB 内存和 16TB NVMe 存储，机身仅 9.78 升。</p><blockquote><p><strong>学习价值</strong>：Linux 硬件评测，与内核学习无关。</p></blockquote><h2 id="版本发布动态" tabindex="-1">版本发布动态 <a class="header-anchor" href="#版本发布动态" aria-label="Permalink to &quot;版本发布动态&quot;">​</a></h2><h3 id="ee224c79aa5b-·-next-20261120-linux-next" tabindex="-1"><code>ee224c79aa5b</code> · <a href="https://www.kernel.org/#kernel.org-linux-next-next-20261120-2026-11-20" target="_blank" rel="noreferrer">next-20261120: linux-next</a> <a class="header-anchor" href="#ee224c79aa5b-·-next-20261120-linux-next" aria-label="Permalink to &quot;`ee224c79aa5b` · [next-20261120: linux-next](https://www.kernel.org/#kernel.org-linux-next-next-20261120-2026-11-20)&quot;">​</a></h3><p><em>kernel.org</em></p><p>linux-next 于 2026-11-20 发布 next-20261120 版本，作为合并到主线前的集成测试树，汇集各子系统分支的待合并补丁。</p><blockquote><p><strong>学习价值</strong>：跟踪 linux-next 发布有助于学习者了解各子系统的最新动向和下个合并窗口的候选内容。</p></blockquote><h2 id="其他动态" tabindex="-1">其他动态 <a class="header-anchor" href="#其他动态" aria-label="Permalink to &quot;其他动态&quot;">​</a></h2><h3 id="dcac4427d4d5-·-bringing-the-agama-installer-to-opensuse-tumbleweed" tabindex="-1"><code>dcac4427d4d5</code> · <a href="https://lwn.net/Articles/1107830/" target="_blank" rel="noreferrer">[$] Bringing the Agama installer to openSUSE Tumbleweed</a> <a class="header-anchor" href="#dcac4427d4d5-·-bringing-the-agama-installer-to-opensuse-tumbleweed" aria-label="Permalink to &quot;`dcac4427d4d5` · [[$] Bringing the Agama installer to openSUSE Tumbleweed](https://lwn.net/Articles/1107830/)&quot;">​</a></h3><p><em>jzb｜lwn｜<strong>LWN 订阅文章，仅预览</strong></em></p><p>openSUSE 项目计划在滚动发行版 Tumbleweed 上全面采用 Agama 安装器。Agama 已是 openSUSE Leap 16.0 的默认安装器，并被其他 openSUSE 版本采纳。社区担心会失去 YaST 的部分传统功能，以及对低内存系统安装的影响。</p><blockquote><p><strong>学习价值</strong>：属于发行版安装器层面的动态，与内核学习关联不大，仅供了解 Linux 生态背景。</p></blockquote><h3 id="_1d2dc2372ddf-·-beyls-wrapping-up-llvm-s-relicensing-effort" tabindex="-1"><code>1d2dc2372ddf</code> · <a href="https://lwn.net/Articles/1108818/" target="_blank" rel="noreferrer">Beyls: Wrapping up LLVM&#39;s relicensing effort</a> <a class="header-anchor" href="#_1d2dc2372ddf-·-beyls-wrapping-up-llvm-s-relicensing-effort" aria-label="Permalink to &quot;`1d2dc2372ddf` · [Beyls: Wrapping up LLVM&#39;s relicensing effort](https://lwn.net/Articles/1108818/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>LLVM 项目宣布历时八年的 relicensing 工作成功收尾。自 2019 年 1 月 19 日起，新贡献均采用 Apache-2.0 WITH LLVM-exception 许可证，旧代码（UIUC/NCSA 及部分 MIT）需作者授权迁移。目前超过 99.5% 的代码已完成许可证转换。</p><blockquote><p><strong>学习价值</strong>：开源许可证治理的典型案例，对理解大型开源项目（包括内核）的合规运作有参考价值。</p></blockquote><h3 id="d9f128fd5f44-·-vim-classic-8-3-1-released" tabindex="-1"><code>d9f128fd5f44</code> · <a href="https://lwn.net/Articles/1108817/" target="_blank" rel="noreferrer">Vim Classic 8.3.1 released</a> <a class="header-anchor" href="#d9f128fd5f44-·-vim-classic-8-3-1-released" aria-label="Permalink to &quot;`d9f128fd5f44` · [Vim Classic 8.3.1 released](https://lwn.net/Articles/1108817/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>Vim Classic 8.3.1 发布，这是一个不借助 LLM 维护的 Vim 长期支持分支。该版本合并了 Vim 8.2.3237 之前的适用补丁，包含大量 bug 修复和插件兼容性改进，并移除了 Python 2 支持。</p><blockquote><p><strong>学习价值</strong>：编辑器工具链新闻，与内核学习无直接关系。</p></blockquote><h3 id="_78c811d67063-·-security-updates-for-friday" tabindex="-1"><code>78c811d67063</code> · <a href="https://lwn.net/Articles/1108811/" target="_blank" rel="noreferrer">Security updates for Friday</a> <a class="header-anchor" href="#_78c811d67063-·-security-updates-for-friday" aria-label="Permalink to &quot;`78c811d67063` · [Security updates for Friday](https://lwn.net/Articles/1108811/)&quot;">​</a></h3><p><em>jzb｜lwn</em></p><p>各发行版发布例行安全更新，涉及 AlmaLinux（含 kernel、kernel-rt、freerdp 等）、Debian（nginx、openjdk-17、php 等）和 Fedora 的众多软件包。</p><blockquote><p><strong>学习价值</strong>：例行安全更新通告，可留意其中 kernel/kernel-rt 相关 CVE 修复动态。</p></blockquote><h3 id="a8d6861ce66d-·-libreboot-abandons-anti-ai-policy-after-one-month" tabindex="-1"><code>a8d6861ce66d</code> · <a href="https://www.phoronix.com/news/Libreboot-Drops-AI-Policy" target="_blank" rel="noreferrer">Libreboot Abandons Anti-AI Policy After One Month</a> <a class="header-anchor" href="#a8d6861ce66d-·-libreboot-abandons-anti-ai-policy-after-one-month" aria-label="Permalink to &quot;`a8d6861ce66d` · [Libreboot Abandons Anti-AI Policy After One Month](https://www.phoronix.com/news/Libreboot-Drops-AI-Policy)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Coreboot 下游项目 Libreboot 上月刚出台禁止 AI/LLM 生成贡献的政策，仅一个月后便撤销该政策，重新允许基于 AI 的提交。</p><blockquote><p><strong>学习价值</strong>：开源社区对 AI 贡献的治理争论案例，与内核学习无直接技术关联。</p></blockquote><h3 id="_766458ca1197-·-gnupg-s-gpgme-affected-by-critical-security-bug-in-turn-affecting-mail-clients-flatpak-1" tabindex="-1"><code>766458ca1197</code> · <a href="https://www.phoronix.com/news/GnuPG-GPGME-Critical" target="_blank" rel="noreferrer">GnuPG&#39;s GPGME Affected By Critical Security Bug In Turn Affecting Mail Clients, Flatpak</a> <a class="header-anchor" href="#_766458ca1197-·-gnupg-s-gpgme-affected-by-critical-security-bug-in-turn-affecting-mail-clients-flatpak-1" aria-label="Permalink to &quot;`766458ca1197` · [GnuPG&#39;s GPGME Affected By Critical Security Bug In Turn Affecting Mail Clients, Flatpak](https://www.phoronix.com/news/GnuPG-GPGME-Critical)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Werner Koch 宣布 GnuPG 的 GPGME 库存在一个 critical 安全漏洞。该漏洞影响大多数邮件客户端、多数 XMPP 客户端、Flatpak、Samba 等依赖 GPGME 的软件。</p><blockquote><p><strong>学习价值</strong>：用户态加密库的安全事件，提醒学习者关注内核之外的供应链安全面。</p></blockquote><h3 id="b3fd41928162-·-intel-preps-linux-7-5-change-to-better-handle-multiple-gpus-with-lots-of-vram-1" tabindex="-1"><code>b3fd41928162</code> · <a href="https://www.phoronix.com/news/Linux-7.5-DRM-8TB-mmap" target="_blank" rel="noreferrer">Intel Preps Linux 7.5 Change To Better Handle Multiple GPUs With Lots Of VRAM</a> <a class="header-anchor" href="#b3fd41928162-·-intel-preps-linux-7-5-change-to-better-handle-multiple-gpus-with-lots-of-vram-1" aria-label="Permalink to &quot;`b3fd41928162` · [Intel Preps Linux 7.5 Change To Better Handle Multiple GPUs With Lots Of VRAM](https://www.phoronix.com/news/Linux-7.5-DRM-8TB-mmap)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Intel 为即将到来的 Linux 7.5 内核周期准备了一项改动，将内核图形驱动中 GEM/TTM buffer object 的 mmap 范围上限从 1TB 扩展到最多 8TB，以更好地支持配备大容量 VRAM 的多 GPU 系统。</p><blockquote><p><strong>学习价值</strong>：涉及 DRM 子系统中 GEM/TTM 内存管理机制，是了解 GPU 显存地址空间管理的实用素材。</p></blockquote><h3 id="f68c07bbcd15-·-amd-contributes-integration-for-content-adaptive-adaptive-backlight-modulation-to-gnome" tabindex="-1"><code>f68c07bbcd15</code> · <a href="https://www.phoronix.com/news/GNOME-AMD-Content-Adaptive" target="_blank" rel="noreferrer">AMD Contributes Integration For Content-Adaptive / Adaptive Backlight Modulation To GNOME</a> <a class="header-anchor" href="#f68c07bbcd15-·-amd-contributes-integration-for-content-adaptive-adaptive-backlight-modulation-to-gnome" aria-label="Permalink to &quot;`f68c07bbcd15` · [AMD Contributes Integration For Content-Adaptive / Adaptive Backlight Modulation To GNOME](https://www.phoronix.com/news/GNOME-AMD-Content-Adaptive)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>AMD 向 GNOME 的 Mutter 合并了 Adaptive Backlight Modulation（ABM）DRM/KMS connector 属性支持和 content-adaptive API。该改进面向现代 AMD Ryzen AI 笔记本，可根据内容自适应调节背光以省电。</p><blockquote><p><strong>学习价值</strong>：展示了 DRM/KMS 属性如何从内核暴露到用户态桌面，有助于理解内核图形栈与用户空间的接口设计。</p></blockquote><h3 id="_296b5d0963dd-·-fedora-incident-response-policy-drafted-for-improving-workflow-security-disclosures" tabindex="-1"><code>296b5d0963dd</code> · <a href="https://www.phoronix.com/news/Fedora-Incident-Response-Policy" target="_blank" rel="noreferrer">Fedora Incident Response Policy Drafted For Improving Workflow &amp; Security Disclosures</a> <a class="header-anchor" href="#_296b5d0963dd-·-fedora-incident-response-policy-drafted-for-improving-workflow-security-disclosures" aria-label="Permalink to &quot;`296b5d0963dd` · [Fedora Incident Response Policy Drafted For Improving Workflow &amp; Security Disclosures](https://www.phoronix.com/news/Fedora-Incident-Response-Policy)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>Fedora Security SIG 起草了一份 Incident Response Policy，旨在改进事件响应流程与安全披露机制。该政策源于 XZ Utils 后门事件中暴露出的 Fedora 项目沟通短板。</p><blockquote><p><strong>学习价值</strong>：开源项目安全事件响应流程的实践案例，对理解安全披露协作有参考意义。</p></blockquote><h3 id="_827ba10c2f54-·-amdxdna-driver-reaches-version-1-0-ryzen-ai-npu10-npu11-coming-to-linux-7-5-1" tabindex="-1"><code>827ba10c2f54</code> · <a href="https://www.phoronix.com/news/AMDXDNA-1.0-Linux-Driver" target="_blank" rel="noreferrer">AMDXDNA Driver Reaches Version 1.0, Ryzen AI NPU10 &amp; NPU11 Coming To Linux 7.5</a> <a class="header-anchor" href="#_827ba10c2f54-·-amdxdna-driver-reaches-version-1-0-ryzen-ai-npu10-npu11-coming-to-linux-7-5-1" aria-label="Permalink to &quot;`827ba10c2f54` · [AMDXDNA Driver Reaches Version 1.0, Ryzen AI NPU10 &amp; NPU11 Coming To Linux 7.5](https://www.phoronix.com/news/AMDXDNA-1.0-Linux-Driver)&quot;">​</a></h3><p><em>Michael Larabel｜phoronix</em></p><p>AMD 的 AMDXDNA 加速器驱动（用于支持 Ryzen AI NPU）将在 Linux 7.5 内核中宣布达到 1.0 版本，标志着该驱动趋于成熟稳定。同时，新一代 NPU10 和 NPU11 硬件的支持也在推进中。</p><blockquote><p><strong>学习价值</strong>：展示了内核加速器驱动从开发到稳定（1.0）的演进过程，适合了解 NPU 驱动子系统的成熟路径。</p></blockquote><h2 id="深读候选" tabindex="-1">深读候选 <a class="header-anchor" href="#深读候选" aria-label="Permalink to &quot;深读候选&quot;">​</a></h2><p>以下条目适合优先深读（按条目前的 id 手动生成）：</p><ul><li><code>9ae505c031bc</code> · <a href="https://lore.kernel.org/all/20261121012402.84848-1-tianyi@cloudflare.com/" target="_blank" rel="noreferrer">[PATCH net] ice: do not report CHECKSUM_COMPLETE when an XDP program is attached</a></li><li><code>6a656cb76a4a</code> · <a href="https://lore.kernel.org/all/20261120-fix-schedstats-bindgen-layout-v2-1-1c42e4a996ae@gmail.com/" target="_blank" rel="noreferrer">[PATCH v2] rust: bindgen: Preserve sched_statistics alignment</a></li></ul>',123)])])}const m=a(n,[["render",l]]);export{u as __pageData,m as default};
